styles:
/* Module 6: keep reveal cards closed and stack teaching diagrams on small screens. */
.char-detail[hidden],.sc-hint[hidden]{display:none}
.char-grid{align-items:start}
@media(max-width:600px){.dc-flow{flex-direction:column;overflow-x:visible}.dc-box{flex:auto;min-width:0;width:100%}.dc-arrow{transform:rotate(90deg);align-self:center}}
